import { initTRPC } from '@trpc/server';
import { createHTTPServer } from '@trpc/server/adapters/standalone';
import {
  createServer,
  IncomingMessage,
  ServerResponse,
} from 'node:http';
import { z } from 'zod';

const t = initTRPC.create({
  sse: {
    client: {
      reconnectAfterInactivityMs: 3_000,
    },
    ping: {
      enabled: true,
      intervalMs: 2_000,
    },
  },
});

const router = t.router;
const publicProcedure = t.procedure;

const countdownRouter = router({
  countdown: publicProcedure
    .input(z.number())
    .subscription(async function* (opts) {
      const from = opts.input;
      for (let i = from; i >= 0; i--) {
        await new Promise((resolve) => setTimeout(resolve, 100));
        yield i;
      }
    }),
});

export type AppRouter = typeof countdownRouter;

// Wrap the standalone HTTP server so we can attach our raw HTTP listener to a
// Node http.Server (allowing us to bind to port 3000 directly without the
// `port` option interfering with the path layout).
const appRouterStandalone = createHTTPServer({
  router: countdownRouter,
});

const httpServer = createServer((req: IncomingMessage, res: ServerResponse) => {
  // tRPC v11's standalone adapter uses fetch-style Request objects under the
  // hood. Forward raw Node requests to it after constructing a Fetch Request.
  const url = `http://${req.headers.host ?? 'localhost'}${req.url ?? '/'}`;

  const headers = new Headers();
  for (const [key, value] of Object.entries(req.headers)) {
    if (value === undefined) continue;
    if (Array.isArray(value)) {
      for (const v of value) headers.append(key, v);
    } else {
      headers.set(key, String(value));
    }
  }

  const chunks: Buffer[] = [];
  req.on('data', (chunk: Buffer) => chunks.push(chunk));
  req.on('end', async () => {
    const method = (req.method ?? 'GET').toUpperCase();
    const init: RequestInit = {
      method,
      headers,
    };
    if (method !== 'GET' && method !== 'HEAD') {
      init.body = Buffer.concat(chunks);
      (init as RequestInit & { duplex?: 'half' }).duplex = 'half';
    }

    const fetchRequest = new Request(url, init);
    const fetchResponse = await appRouterStandalone.fetch(fetchRequest);

    res.statusCode = fetchResponse.status;
    fetchResponse.headers.forEach((value, key) => {
      res.setHeader(key, value);
    });

    if (fetchResponse.body) {
      const reader = fetchResponse.body.getReader();
      const pump = async () => {
        while (true) {
          const { done, value } = await reader.read();
          if (done) {
            res.end();
            return;
          }
          res.write(Buffer.from(value));
        }
      };
      pump().catch((err) => {
        console.error('SSE stream error:', err);
        res.end();
      });
    } else {
      res.end();
    }
  });
});

httpServer.listen(3000, () => {
  console.log('tRPC server listening on http://localhost:3000');
});

