import {
  createTRPCClient,
  httpSubscriptionLink,
  splitLink,
  httpBatchLink,
  TRPCLink,
} from '@trpc/client';
import { observable } from '@trpc/server/observable';
import type { AppRouter } from './server';

const url = 'http://localhost:3000';

const trpc = createTRPCClient<AppRouter>({
  links: [
    splitLink({
      condition: (op) => op.type === 'subscription',
      true: httpSubscriptionLink({
        url,
        // EventSource doesn't support custom headers in browsers, but the
        // Node `EventSource` polyfill used by tRPC does. We pass nothing
        // extra here.
      }),
      false: httpBatchLink({ url }),
    }),
  ],
});

async function main() {
  const subscription = trpc.countdown.subscribe(3, {
    onData: (value) => {
      console.log(value);
    },
    onError: (err) => {
      console.error('Subscription error:', err);
    },
    onComplete: () => {
      console.log('Subscription complete');
      process.exit(0);
    },
  });

  // Allow some headroom in case the onComplete callback never fires.
  setTimeout(() => {
    subscription.unsubscribe();
    process.exit(0);
  }, 5_000);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

